"use client";

import { useEffect, useState } from "react";
import { usePathname } from "next/navigation";

/**
 * Google Analytics 4 – wird erst nach Einwilligung („Statistik“ im Cookie-Banner) geladen.
 *
 * Umgebungsvariable: NEXT_PUBLIC_GA_ID (Mess-ID, z. B. G-XXXXXXXXXX)
 *
 * - Vor der Einwilligung: kein Skript, keine Verbindung zu Google, keine Cookies.
 * - Google Consent Mode v2: Standard „denied“, nach Einwilligung nur analytics_storage „granted“
 *   (keine Werbe-/Personalisierungsfreigaben).
 * - Widerruf: Messung wird sofort gestoppt und die _ga-Cookies werden gelöscht.
 * - Seiten mit Einmal-Tokens (/scan, /fortsetzen, /angebot) und die Info-Bildschirme (/tv) werden nie gemessen;
 *   von URL-Parametern werden nur utm_* übertragen.
 */
// Eigene GA4-Property für ÖkoInvest – ohne Mess-ID wird nichts geladen (nie die ID der DE-Seite)
const GA_ID = process.env.NEXT_PUBLIC_GA_ID || null;
const AUSGENOMMEN = /^\/(scan|fortsetzen|tv|angebot)(\/|$)/; // angebot: persönliche Einmalcodes der Akquise-Kampagnen

export function statistikErlaubt() {
  if (typeof document === "undefined") return false;
  try {
    const roh = document.cookie.split("; ").find((c) => c.startsWith("cookieConsent="));
    if (!roh) return false;
    return JSON.parse(decodeURIComponent(roh.slice("cookieConsent=".length))).googleAnalytics === true;
  } catch {
    return false;
  }
}

function gtagVorbereiten() {
  window.dataLayer = window.dataLayer || [];
  if (!window.gtag) {
    window.gtag = function () {
      window.dataLayer.push(arguments);
    };
    window.gtag("consent", "default", {
      analytics_storage: "denied",
      ad_storage: "denied",
      ad_user_data: "denied",
      ad_personalization: "denied",
    });
  }
}

function laden() {
  window[`ga-disable-${GA_ID}`] = false;
  gtagVorbereiten();
  window.gtag("consent", "update", { analytics_storage: "granted" });
  if (window.ovGaGeladen) return;
  window.ovGaGeladen = true;
  window.gtag("js", new Date());
  // Seitenaufrufe senden wir selbst (bereinigte URL, Ausnahmen) – daher send_page_view: false
  window.gtag("config", GA_ID, { send_page_view: false, allow_google_signals: false, allow_ad_personalization_signals: false });
  const s = document.createElement("script");
  s.src = `https://www.googletagmanager.com/gtag/js?id=${GA_ID}`;
  s.async = true;
  document.head.appendChild(s);
}

function stoppen() {
  window[`ga-disable-${GA_ID}`] = true;
  if (window.gtag) window.gtag("consent", "update", { analytics_storage: "denied" });
  // _ga und _ga_<ID> auf allen passenden Domain-Ebenen löschen
  const teile = location.hostname.split(".");
  const domains = ["", ...teile.map((_, i) => "." + teile.slice(i).join("."))];
  document.cookie.split("; ").forEach((c) => {
    const name = c.split("=")[0];
    if (!/^_ga(_|$)/.test(name)) return;
    domains.forEach((d) => {
      document.cookie = `${name}=; Max-Age=0; path=/${d ? `; domain=${d}` : ""}`;
    });
  });
}

function seitenaufruf(pfad) {
  if (!window.ovGaGeladen || window[`ga-disable-${GA_ID}`] || AUSGENOMMEN.test(pfad)) return;
  const url = new URL(window.location.href);
  const utm = new URLSearchParams();
  url.searchParams.forEach((w, k) => {
    if (/^utm_(source|medium|campaign|term|content)$/.test(k)) utm.set(k, w.slice(0, 100));
  });
  const q = utm.toString();
  window.gtag("event", "page_view", {
    page_location: `${url.origin}${pfad}${q ? `?${q}` : ""}`,
    page_path: pfad,
    page_title: document.title,
  });
}

export default function GoogleAnalytics() {
  const pfad = usePathname();
  const [erlaubt, setErlaubt] = useState(null); // null = noch nicht geprüft

  useEffect(() => {
    const pruefen = () => setErlaubt(statistikErlaubt());
    pruefen();
    window.addEventListener("ov-consent", pruefen);
    return () => window.removeEventListener("ov-consent", pruefen);
  }, []);

  useEffect(() => {
    if (!GA_ID) return;
    if (erlaubt) laden();
    else if (erlaubt === false) stoppen(); // auch alte _ga-Cookies nach einem Widerruf entfernen
  }, [erlaubt]);

  useEffect(() => {
    if (GA_ID && erlaubt) seitenaufruf(pfad);
  }, [erlaubt, pfad]);

  return null;
}
// src/lib/herkunft.js
//
// Kampagnen-Zuordnung für Anfragen – bewusst OHNE Cookies und OHNE Browserspeicher:
// Beim ersten Seitenaufruf werden UTM-Parameter, verweisende Domain und Einstiegsseite
// im Arbeitsspeicher der geöffneten Website gehalten (bleibt bei Navigation innerhalb der Seite
// erhalten, endet beim Schließen/Neuladen). Übertragen wird nur zusammen mit einer Anfrage.

let erfasst = null;

const UTM = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"];
const kurz = (v, n = 100) => String(v || "").replace(/[^\p{L}\p{N} _.\-/:+|]/gu, "").slice(0, n);

function eigeneDomain(host) {
  return /(^|\.)oekoinvest\.(com|at|de|ch)$/.test(host) || host === location.host;
}

/** Einmalig beim ersten Laden aufrufen (HerkunftErfassen in LayoutWrapper). */
export function herkunftErfassen() {
  if (typeof window === "undefined" || erfasst) return;
  const url = new URL(window.location.href);
  const utm = Object.fromEntries(UTM.map((k) => [k, kurz(url.searchParams.get(k))]).filter(([, v]) => v));

  let referrer = "";
  try {
    const r = document.referrer ? new URL(document.referrer) : null;
    if (r && !eigeneDomain(r.host)) referrer = r.host.replace(/^www\./, "");
  } catch {
    /* ungültig */
  }

  // Einmal-Tokens nie übernehmen
  const einstieg = url.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200);
  erfasst = { ...utm, referrer, einstieg, zeit: new Date().toISOString() };
}

/** Kanal grob klassifizieren (für Auswertungen). */
function kanal(h) {
  const medium = (h.utm_medium || "").toLowerCase();
  if (h.utm_source || h.utm_medium) {
    if (/cpc|ppc|paid|ads?$/.test(medium)) return "Anzeige";
    if (/social/.test(medium)) return "Social Media";
    if (/mail|newsletter/.test(medium)) return "E-Mail";
    if (/qr|print|flyer|offline/.test(medium)) return "Offline/QR";
    return "Kampagne";
  }
  const r = h.referrer || "";
  if (!r) return "Direkt";
  if (/google\.|bing\.|duckduckgo\.|ecosia\.|yahoo\.|qwant\./.test(r)) return "Suchmaschine";
  if (/chatgpt\.com|openai\.com|perplexity\.ai|claude\.ai|gemini\.google|copilot\.microsoft/.test(r)) return "KI-Assistent";
  if (/facebook\.|instagram\.|linkedin\.|xing\.|t\.co$|x\.com|threads\.net|mastodon|social\.|youtube\./.test(r)) return "Social Media";
  return "Verweis";
}

/** Daten zum Mitsenden mit einer Anfrage. `seite` = aktuelle Seite. */
export function herkunft() {
  if (typeof window === "undefined") return null;
  if (!erfasst) herkunftErfassen();
  const h = erfasst || {};
  return { ...h, kanal: kanal(h), seite: window.location.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200) };
}

/** Kompakte Textzeile für Backends ohne eigene Felder (z. B. bestehende Kontaktanfrage). */
export function herkunftText(h = herkunft()) {
  if (!h) return "";
  const teile = [
    `Kanal: ${h.kanal}`,
    h.utm_source && `Quelle: ${h.utm_source}`,
    h.utm_medium && `Medium: ${h.utm_medium}`,
    h.utm_campaign && `Kampagne: ${h.utm_campaign}`,
    h.utm_term && `Keyword: ${h.utm_term}`,
    h.referrer && `Verweis: ${h.referrer}`,
    h.einstieg && `Einstieg: ${h.einstieg}`,
    h.seite && `Seite: ${h.seite}`,
  ].filter(Boolean);
  return `[Herkunft] ${teile.join(" · ")}`;
}
// Ereignisse für Google Analytics – werden nur gesendet, wenn der Besucher der Statistik zugestimmt hat
// (window.gtag existiert erst nach Einwilligung, siehe components/Statistik/GoogleAnalytics.js).
// Niemals personenbezogene Daten übergeben (keine Namen, E-Mails, Telefonnummern, Tokens).

const ERLAUBT = /^[a-z0-9_]{2,40}$/;

export function ereignis(name, daten) {
  if (typeof window === "undefined" || !ERLAUBT.test(name)) return;
  try {
    const sauber = daten
      ? Object.fromEntries(
          Object.entries(daten)
            .filter(([, v]) => ["string", "number", "boolean"].includes(typeof v))
            .map(([k, v]) => [k.slice(0, 40), typeof v === "string" ? v.slice(0, 80) : v])
        )
      : undefined;
    if (window.ovGaGeladen) window.gtag?.("event", name, sauber);
  } catch {
    /* Statistik darf nie stören */
  }
}

